<?php
namespace App\Models;
use App\Enums\UserRole; use Illuminate\Contracts\Auth\MustVerifyEmail; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; use Laravel\Sanctum\HasApiTokens;
class User extends Authenticatable implements MustVerifyEmail { use HasApiTokens, HasFactory, Notifiable; protected $fillable=['name','email','password','role','email_verified_at']; protected $hidden=['password','remember_token']; protected function casts(): array { return ['email_verified_at'=>'datetime','password'=>'hashed','role'=>UserRole::class]; } public function doctor(){ return $this->hasOne(Doctor::class); } public function patient(){ return $this->hasOne(Patient::class); } public function isRole(string $role): bool { return $this->role?->value === $role; } }
